CHROME_DEVTOOLS_AXI_HEADED=1 chrome-devtools-axi open "http://127.0.0.1:5051/?nocache=$(date +%s)" 2>&1; chrome-devtools-axi resize 1280 800 2>&1; chrome-devtools-axi wait 1500 2>&1; chrome-devtools-axi eval '
(() => {
  const sel = document.getElementById("traceSelect");
  const trig = document.getElementById("preloadedTrigger");
  const tour = document.getElementById("uiTour");
  const cs = sel ? getComputedStyle(sel) : null;
  const r = sel ? sel.getBoundingClientRect() : null;
  const tr = trig ? trig.getBoundingClientRect() : null;
  const tcs = trig ? getComputedStyle(trig) : null;
  return JSON.stringify({
    vw: window.innerWidth,
    tourHidden: tour ? tour.hidden : null,
    tourClasses: tour ? tour.className : null,
    select: sel && {
      className: sel.className,
      options: sel.options.length,
      value: sel.value,
      rect: {w: r.width, h: r.height, x: r.x, y: r.y},
      display: cs.display, visibility: cs.visibility, opacity: cs.opacity,
      width: cs.width, height: cs.height, clip: cs.clip, position: cs.position,
      overflow: cs.overflow, pointerEvents: cs.pointerEvents, border: cs.border,
      appearance: cs.appearance || cs.webkitAppearance
    },
    trigger: trig && {
      display: tcs.display,
      rect: {w: tr.width, h: tr.height, x: tr.x, y: tr.y},
      text: document.getElementById("preloadedLabel")?.textContent
    }
  }, null, 2);
}')' 2>&1
